/* Authentic-photo context panels and substantive interactive practice, original A1.1 companion content. */
(()=>{'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const activities={
2:{title:'Plan a day with a friend',prompt:'Select a day and an activity. Your plan and German invitation change together.',a:['Montag','Mittwoch','Freitag','Samstag'],b:['ins Kino gehen','schwimmen gehen','Fußball spielen','Rad fahren'],make:(a,b)=>['Hast du am '+a+' Zeit?','Ja, gern! Wir können '+b+'.'],labels:['Day','Activity']},
3:{title:'Follow a route through town',prompt:'Choose a destination. Follow the highlighted numbered route on the original schematic map.',a:['Bahnhof','Park','Rathaus','Hotel'],b:['geradeaus','links','rechts'],make:(a,b)=>['Entschuldigung, wo ist '+({Bahnhof:'der Bahnhof',Park:'der Park',Rathaus:'das Rathaus',Hotel:'das Hotel'}[a])+'?','Gehen Sie '+b+'.'],labels:['Destination','Direction']},
4:{title:'Make a shopping list',prompt:'Choose two groceries. See how the accusative changes a masculine article.',a:['das Brot','den Käse','die Milch','die Tomaten'],b:['das Brot','den Käse','die Milch','die Tomaten'],make:(a,b)=>['Ich brauche '+a+' und '+b+'.','Haben Sie '+a+'?'],labels:['First item','Second item']},
5:{title:'Set an appointment',prompt:'Select an appointment time and day. Notice the difference between the digital clock and spoken German.',a:['08:00','08:15','08:30','08:45'],b:['Montag','Dienstag','Mittwoch','Freitag'],make:(a,b)=>['Haben Sie am '+b+' um '+a+' Uhr Zeit?','Ja, am '+b+' um '+a+' Uhr.'],labels:['Time','Day']},
6:{title:'Create a complete invitation',prompt:'Choose a day and an activity to write a short original invitation.',a:['Freitag','Samstag','Sonntag','Mittwoch'],b:['ins Kino','ins Restaurant','zum Fußball','ins Café'],make:(a,b)=>['Hast du am '+a+' Zeit?','Ich lade dich '+b+' ein.'],labels:['Day','Place / activity']}
};
const icons={2:['🚴','💼','📅'],3:['🏙️','🚋','🧭'],4:['🥖','🥬','🛍️'],5:['⏰','👨‍👩‍👧','📆'],6:['🎂','🍽️','☕']};
function render(n){const d=activities[n];if(!d)return '';const photos=window.GERMAN_RICH_SCENES?.data?.chapters?.[n]||[];
return `<section class="a11-premium" id="chapter-${n}-photo-studio" aria-label="Chapter ${n} photographic and interactive learning"><header><span class="eyebrow">Chapter ${n} · Explore authentic situations</span><h5>See German in real life</h5><p>Examine the scene, listen to its German expression and follow its original practice cue. These licensed photographs illustrate real settings; they are not textbook reproductions.</p></header>
<div class="a11-premium-photos">${photos.map((p,i)=>`<figure><div class="a11-premium-photo"><img src="${esc(p.src)}" alt="${esc(p.alt)}" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false" /><span hidden aria-hidden="true" class="a11-premium-fallback">${icons[n][i]||'🖼️'}</span></div><figcaption><strong>${esc(p.title)}</strong><span lang="de">${esc(p.de)}</span><small>${esc(p.cue)}</small><button type="button" data-photo-speak="${esc(p.de)}">♫ Listen</button><a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Photo: ${esc(p.credit)}</a></figcaption></figure>`).join('')}</div>
<div class="a11-premium-simulator" data-premium="${n}"><h6>${esc(d.title)}</h6><p>${esc(d.prompt)}</p>
<div class="a11-premium-controls">${[d.a,d.b].map((vals,i)=>`<label>${esc(d.labels[i])}<select data-premium-select="${i}">${vals.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`).join('')}</div>
<div class="a11-premium-output"><strong lang="de" data-premium-line="0">${esc(d.make(d.a[0],d.b[0])[0])}</strong><p lang="de" data-premium-line="1">${esc(d.make(d.a[0],d.b[0])[1])}</p><button type="button" data-premium-listen>♫ Listen to both lines</button></div>
${n===3?'<div class="a11-premium-mini-map" aria-label="Original schematic town: Station top left, park top right, town hall bottom left, hotel bottom right"><span>🚉 Bahnhof</span><span>🌳 Park</span><span>🏛️ Rathaus</span><span>🏨 Hotel</span></div>':''}
${n===5?'<div class="a11-premium-clock" role="img" aria-label="An analogue clock with hands that update to the selected time"><span class="a11-premium-hour"></span><span class="a11-premium-minute"></span><span class="a11-premium-center"></span></div>':''}
<p class="a11-premium-note">Practice using these model phrases with your teacher or a classmate.</p></div></section>`;}
function init(root=document){root.querySelectorAll('[data-premium]').forEach(el=>{const n=Number(el.dataset.premium),d=activities[n];const selects=[...el.querySelectorAll('[data-premium-select]')];function change(){const [a,b]=selects.map(x=>x.value),lines=d.make(a,b);el.querySelector('[data-premium-line="0"]').textContent=lines[0];el.querySelector('[data-premium-line="1"]').textContent=lines[1];if(n===5){const [hour,minute]=a.split(':').map(Number);el.style.setProperty('--minute-angle',minute*6+'deg');el.style.setProperty('--hour-angle',((hour%12)*30+minute*.5)+'deg');}if(n===3){const cells=el.querySelectorAll('.a11-premium-mini-map span');cells.forEach(x=>x.classList.toggle('is-destination',x.textContent.includes(a)));}}selects.forEach(s=>s.addEventListener('change',change));change();el.querySelector('[data-premium-listen]').addEventListener('click',()=>speak([...el.querySelectorAll('[data-premium-line]')].map(x=>x.textContent).join(' ')));});root.querySelectorAll('[data-photo-speak]').forEach(b=>b.addEventListener('click',()=>speak(b.dataset.photoSpeak)));}
function speak(t){if(!('speechSynthesis' in window))return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='de-DE';u.rate=.84;speechSynthesis.speak(u);}catch(_){}}
window.GERMAN_A11_PHOTO_STUDIO={render,init};
})();